import {quotaLabel} from './quota.js';
export const STORAGE_KEY='cloud-trails-reader-v1';
export const normalize=(value)=>String(value||'').normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim();
export function validIds(values,known,max=4){return [...new Set(Array.isArray(values)?values:[])].filter(id=>known.has(id)).slice(0,max);}
export function cleanState(raw,known,paths){return {favorites:validIds(raw?.favorites,known,28),compare:validIds(raw?.compare,known,4),recent:[...new Set(Array.isArray(raw?.recent)?raw.recent:[])].filter(p=>paths.has(p)).slice(0,12)};}
export function toggleComparison(ids,id){if(ids.includes(id))return {ids:ids.filter(x=>x!==id),full:false};if(ids.length===4)return {ids,full:true};return {ids:[...ids,id],full:false};}
export function searchCatalog(documents,query,type='all'){const terms=normalize(query).split(' ').filter(Boolean);return documents.filter(d=>(type==='all'||d.type===type)&&terms.every(t=>normalize(d.title+' '+d.text+' '+d.description).includes(t))).map(d=>({d,score:terms.reduce((n,t)=>n+(normalize(d.title).includes(t)?4:1),0)})).sort((a,b)=>b.score-a.score).map(x=>x.d);}
export function planMetrics(b){if(b.planAttribution==='disputed')return {monthly:{price:null,gb:null},annual:null};const monthly=b.plans.filter(p=>p.cycle==='月付').sort((a,c)=>a.price-c.price)[0],annual=b.plans.filter(p=>p.cycle==='年付').sort((a,c)=>a.price-c.price)[0];return {monthly,annual};}
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
if(typeof document!=='undefined'){
 const script=document.querySelector('script[data-reader-module]'),base=new URL('../',script.src);let state,catalog,known,paths,documents;let storageAvailable=true;
 const url=p=>new URL(p,base).href;
 function announce(message){const toast=document.querySelector('.toast');toast.textContent=message;toast.classList.add('visible');clearTimeout(announce.timer);announce.timer=setTimeout(()=>toast.classList.remove('visible'),3200);}
 function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch{storageAvailable=false;}sync();}
 function sync(){document.querySelectorAll('[data-save-brand]').forEach(b=>{b.disabled=false;const saved=state.favorites.includes(b.dataset.saveBrand);b.textContent=saved?'★ 已收藏':'☆ 收藏';b.setAttribute('aria-pressed',String(saved));});document.querySelectorAll('[data-compare-brand]').forEach(b=>{b.disabled=false;const selected=state.compare.includes(b.dataset.compareBrand);b.textContent=selected?'✓ 已选对比':'＋ 加入对比';b.setAttribute('aria-pressed',String(selected));});
 const tray=document.querySelector('#reader-compare-tray');tray.hidden=state.compare.length===0||!!document.querySelector('#comparison-choices');document.body.classList.toggle('has-compare-tray',!tray.hidden);document.querySelectorAll('[data-close-choice]').forEach(b=>b.disabled=state.compare.length<2);tray.querySelector('[data-selected-names]').textContent=state.compare.map(id=>catalog.brands.find(b=>b.id===id).name).join(' · ');tray.querySelector('[data-compare-count]').textContent='已选 '+state.compare.length+' / 4';tray.querySelector('[data-open-comparison]').disabled=state.compare.length<2;
 if(!storageAvailable)document.querySelectorAll('[data-storage-notice]').forEach(e=>{e.hidden=false;e.textContent='浏览器未允许本地保存；本页操作仍可使用，刷新或离开后可能丢失。';});}
 function documentCard(d){return '<article class="reader-card"><span class="reader-kind">'+({brand:'品牌资料',article:'博客文章',topic:'推荐专题'}[d.type])+'</span><h2><a href="'+url(d.path)+'">'+escape(d.title)+'</a></h2><p>'+escape(d.description)+'</p><a class="text-link" href="'+url(d.path)+'">打开阅读 →</a></article>';}
 function renderLibrary(){const favorites=document.querySelector('#saved-brands'),recent=document.querySelector('#recent-reading');if(!favorites)return;favorites.innerHTML=state.favorites.length?state.favorites.map(id=>{const d=documents.find(d=>d.type==='brand'&&d.id===id);return '<div class="saved-item">'+documentCard(d)+'<button class="reader-action" data-remove-favorite="'+id+'" aria-label="取消收藏 '+escape(d.title)+'">取消收藏</button></div>';}).join(''):'<p class="reader-empty">还没有收藏品牌。到<a href="'+url('#brands')+'">品牌目录</a>点击“收藏”，即可在这里找到。</p>';recent.innerHTML=state.recent.length?state.recent.map(p=>documentCard(documents.find(d=>d.path===p))).join(''):'<p class="reader-empty">浏览品牌、文章或专题后，这里会记录最近打开的内容。</p>';}
 function renderCompare(ids){const host=document.querySelector('#picked-brand-comparison');if(!host)return;const selected=ids.map(id=>catalog.brands.find(b=>b.id===id));const rows=document.querySelector('#comparison-choices');rows.querySelectorAll('input').forEach(input=>input.checked=ids.includes(input.value));const summary=document.querySelector('#picked-compare-status');summary.textContent=selected.length<2?'请勾选 2～4 家品牌，再查看相同口径的差异。':'正在比较 '+selected.length+' 家品牌；均为第三方参考，优惠未计入价格。';const overview=selected.length<2?'':'<div class="picked-summary"><h3>金额与流量速览</h3><div class="table-scroll"><table><caption>最低档参考金额 · 未计优惠</caption><thead><tr><th>品牌</th><th>月付</th><th>该档流量</th><th>年付总价</th></tr></thead><tbody>'+selected.map(b=>{const {monthly:m,annual:a}=planMetrics(b);return '<tr><th><a href="'+url('brands/'+b.id+'/')+'">'+escape(b.name)+'</a></th><td>'+ (m.price===null?'归属待核实':'¥'+m.price) +'</td><td>'+(m.gb===null?'待核验':m.gb+'GB/月')+'</td><td>'+(b.planAttribution==='disputed'?'归属待核实':a?'¥'+a.price:'资料待补')+'</td></tr>';}).join('')+'</tbody></table></div><p>年付需一次支付全年，容量请看下方详情；月包容量不同，起价不能直接当作同用量结论。</p></div>';host.innerHTML=selected.length<2?'':overview+selected.map(b=>{const {monthly:m,annual:a}=planMetrics(b);return '<article class="picked-brand"><div class="picked-header"><h3><a href="'+url('brands/'+b.id+'/')+'">'+escape(b.name)+'</a></h3><button class="reader-action" data-remove-compare="'+b.id+'" aria-label="移除 '+escape(b.name)+'">移除</button></div><dl><div><dt>最低参考月付</dt><dd>'+ (m.price===null?'归属待核实':'¥'+m.price+' / 月') +'</dd></div><div><dt>该档月流量</dt><dd>'+(m.gb===null?'待核验':m.gb+'GB / 月')+'</dd></div><div><dt>该档标称成本</dt><dd>'+(m.gb===null?'待核验':'¥'+(m.price/m.gb).toFixed(3)+' / GB')+'</dd></div><div><dt>最低参考年付</dt><dd>'+(b.planAttribution==='disputed'?'归属待核实':a?'¥'+a.price+' / 年，'+escape(quotaLabel(a)):'资料待补')+'</dd></div><div><dt>一次性包</dt><dd>'+(b.planAttribution==='disputed'?'归属待核实，暂停推荐':b.plans.some(p=>p.cycle==='一次性')?'收录有相关档位':'未收录，不代表没有')+'</dd></div><div><dt>优惠码</dt><dd>'+(b.coupon?escape(b.coupon)+' · 待验证':'未提供')+'</dd></div><div><dt>适合的用量</dt><dd>'+escape(b.planAttribution==='disputed'?'先确认套餐与入口的对应关系':b.audience)+'</dd></div><div><dt>需要核对</dt><dd>'+escape(b.note)+'</dd></div><div><dt>来源记录日期</dt><dd>'+escape(b.plans[0].sourceDate)+'</dd></div><div><dt>当前官网价格</dt><dd>尚未独立确认</dd></div></dl><a class="button secondary" href="'+url('brands/'+b.id+'/')+'">完整套餐与资料来源</a></article>';}).join('');host.style.setProperty('--picked-columns',String(Math.max(2,selected.length)));}
 function saveCompareURL(ids){const link=new URL(location.href);if(ids.length)link.searchParams.set('brands',ids.join(','));else link.searchParams.delete('brands');history.replaceState(null,'',link);}
 async function init(){const response=await fetch(new URL(document.querySelector('#site-search-form')?'catalog.json':'reader-catalog.json',script.src));if(!response.ok)throw Error('Catalog unavailable');catalog=await response.json();documents=catalog.documents;known=new Set(catalog.brands.map(b=>b.id));paths=new Set(documents.map(d=>d.path));let raw;try{raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null');}catch{storageAvailable=false;}state=cleanState(raw,known,paths);
 const current=documents.find(d=>new URL(d.path,base).pathname===location.pathname.replace(/index.html$/,''));if(current){state.recent=[current.path,...state.recent.filter(p=>p!==current.path)].slice(0,12);persist();}else sync();
 document.querySelectorAll('[data-reader-loading]').forEach(e=>e.hidden=true);
 document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const id=button.dataset.saveBrand||button.dataset.removeFavorite;if(id&&known.has(id)){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];persist();renderLibrary();return;}const compareId=button.dataset.compareBrand||button.dataset.removeCompare;if(compareId&&known.has(compareId)){const result=toggleComparison(state.compare,compareId);if(result.full){announce('最多同时比较 4 家，请先移除一个品牌。');return;}state.compare=result.ids;persist();if(document.querySelector('#picked-brand-comparison')){saveCompareURL(state.compare);renderCompare(state.compare);}return;}if(button.hasAttribute('data-close-choice')){document.querySelector('.compare-choice-picker').open=false;document.querySelector('#picked-compare-status').scrollIntoView({block:'start',behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'});}if(button.hasAttribute('data-clear-comparison')){state.compare=[];persist();if(document.querySelector('#picked-brand-comparison')){saveCompareURL([]);renderCompare([]);}}if(button.hasAttribute('data-open-comparison')&&state.compare.length>=2)location.href=url('compare/?brands='+state.compare.join(',')+'#pick-compare');if(button.hasAttribute('data-clear-recent')){state.recent=[];persist();renderLibrary();}if(button.hasAttribute('data-clear-favorites')){state.favorites=[];persist();renderLibrary();}});
 renderLibrary();
 const choices=document.querySelector('#comparison-choices');if(choices){const params=new URL(location.href).searchParams;if(params.has('brands')){state.compare=validIds(params.get('brands').split(','),known,4);persist();}renderCompare(state.compare);if(state.compare.length>=2&&window.matchMedia('(max-width:760px)').matches)document.querySelector('.compare-choice-picker').open=false;choices.addEventListener('change',event=>{const input=event.target;if(!known.has(input.value))return;const result=toggleComparison(state.compare,input.value);if(result.full){input.checked=false;announce('最多同时比较 4 家，请先取消一个品牌。');return;}state.compare=result.ids;persist();saveCompareURL(state.compare);renderCompare(state.compare);});}
 const form=document.querySelector('#site-search-form');if(form){const input=form.querySelector('input'),type=form.querySelector('select'),results=document.querySelector('#site-search-results'),status=document.querySelector('#site-search-status'),pager=document.querySelector('#site-search-more');let found=[],limit=12;
 const render=()=>{results.innerHTML=found.length?found.slice(0,limit).map(documentCard).join(''):'<p class="reader-empty">没有找到匹配内容。试试品牌名、预算、流量或更短的关键词。</p>';status.textContent=input.value.trim()?'找到 '+found.length+' 条结果，显示前 '+Math.min(limit,found.length)+' 条':'可搜索 '+documents.length+' 条品牌、文章与专题，当前展示 '+Math.min(limit,found.length)+' 条';pager.hidden=limit>=found.length;};
 const apply=()=>{limit=12;found=searchCatalog(documents,input.value,type.value);render();};input.value=new URL(location.href).searchParams.get('q')||'';form.addEventListener('submit',event=>{event.preventDefault();apply();const u=new URL(location.href);if(input.value.trim())u.searchParams.set('q',input.value.trim());else u.searchParams.delete('q');history.replaceState(null,'',u);});input.addEventListener('input',apply);type.addEventListener('change',apply);pager.addEventListener('click',()=>{limit+=12;render();});apply();}
 window.addEventListener('storage',event=>{if(event.key!==STORAGE_KEY)return;try{state=cleanState(JSON.parse(event.newValue||'null'),known,paths);sync();renderLibrary();renderCompare(state.compare);}catch{}});
 }
 init().catch(()=>{document.querySelectorAll('[data-reader-loading]').forEach(e=>{e.hidden=false;e.textContent='暂时无法载入互动功能，请刷新后重试；静态品牌资料与文章仍可正常阅读。';});document.querySelectorAll('[data-save-brand],[data-compare-brand]').forEach(b=>b.disabled=true);});
}
